def assign_original_prices(apps, schema_editor):
    """ILS-only products become an ILS original. Products with both bases stay for review."""
    Currency = apps.get_model("shop", "Currency")
    Product = apps.get_model("shop", "Product")
    for code, name, symbol in (
        ("CNY", "Chinese Yuan Renminbi", "¥"),
        ("USD", "US Dollar", "$"),
        ("ILS", "Israeli Shekel", "₪"),
    ):
        Currency.objects.get_or_create(code=code, defaults={"name": name, "symbol": symbol, "decimal_places": 2})
    for product in Product.objects.all():
        if product.base_price_usd is None:
            product.original_currency_id = "ILS"
            product.original_price = product.base_price_ils
            product.price_review_required = False
        else:
            product.price_review_required = True
        product.save(update_fields=["original_currency", "original_price", "price_review_required"])


